(function(root){'use strict';const TEMPLATE="<!doctype html><html lang=\"pt-BR\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><title>Evolução de idade das fêmeas | Fazenda Bodoquena</title><style>\n:root{--green:#193e32;--paper:#faf9f4;--muted:#617065}*{box-sizing:border-box}body{margin:0;background:#e4e9e4;color:var(--green);font:15px Arial,sans-serif}.report{max-width:1170px;margin:24px auto;background:var(--paper);box-shadow:0 6px 28px #193e3222}.brand{position:relative;aspect-ratio:1170/80;overflow:hidden}.brand img,.landscape img{position:absolute;width:100%;left:0}.brand img{top:0}.landscape{position:relative;aspect-ratio:1170/193;overflow:hidden;margin-top:28px}.landscape img{bottom:0}main{padding:28px 42px 0}h1{font-size:28px;margin:0 0 8px}h2{font-size:19px;margin:0 0 18px}.sub,.note{color:var(--muted);line-height:1.5}.sub{margin:0 0 22px}.filters{display:flex;flex-wrap:wrap;gap:14px;background:#eef2e9;padding:18px;border:1px solid #dce3d6;border-radius:8px;margin-bottom:22px}.field{display:flex;flex:1;min-width:140px;flex-direction:column;gap:7px;font-size:12px;font-weight:bold}.field.wide{flex:2}select,input,button{font:14px Arial;min-height:42px;border:1px solid #cbd5c7;border-radius:5px;background:white;color:var(--green);padding:9px 12px}button{cursor:pointer;background:var(--green);color:white;border:0;align-self:end}.context{font-weight:bold;margin:0 0 17px}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-bottom:28px}.card{background:#fffefa;border:1px solid #dce3d6;border-radius:7px;padding:17px}.label{font-size:11px;color:var(--muted);text-transform:uppercase;font-weight:bold}.value{font-size:27px;font-weight:bold;margin:9px 0 4px}.small{font-size:12px;color:var(--muted)}.block{margin:0 0 30px}.chart-wrap{overflow:auto}#chart{display:block;width:100%;min-width:640px;height:auto}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;font-size:13px;white-space:nowrap}th{background:var(--green);color:white;padding:11px 9px}th:first-child{text-align:left}td{padding:8px 9px;text-align:right;border-bottom:1px solid #e3e8de;color:#193e32}td:first-child{text-align:left;background:#fffefa}tfoot td{font-weight:bold;border-top:2px solid #b8c4b2}.legend{display:flex;gap:16px;flex-wrap:wrap;font-size:12px;margin-top:12px;color:var(--muted)}.dot{display:inline-block;width:12px;height:12px;border-radius:3px;vertical-align:-2px;margin-right:5px}.note{font-size:12px;margin-bottom:0}#error{color:#973b28} @media(max-width:650px){.report{margin:0}main{padding:22px 16px 0}h1{font-size:23px}.cards{grid-template-columns:1fr;gap:9px}.card{padding:12px}.value{font-size:24px}.field{min-width:110px}.landscape{margin-top:20px}}@page{size:A4 landscape;margin:12mm}@media print{body{background:white;font-size:12px}.report{margin:0;max-width:none;box-shadow:none}.filters{display:none}main{padding:16px 20px 0}.cards{grid-template-columns:repeat(3,1fr);break-inside:avoid}.block{margin-bottom:18px}.table-wrap{overflow:visible}table{font-size:10px}th,td{padding:6px}tr{break-inside:avoid}thead{display:table-header-group}tfoot{display:table-row-group}.chart-wrap{overflow:visible}#chart{min-width:0}.landscape{break-inside:avoid}*{-webkit-print-color-adjust:exact;print-color-adjust:exact}}\n</style></head><body><article class=\"report\"><header class=\"brand\"><img src=\"data:image/jpeg;base64,\" alt=\"Fazenda Bodoquena — Pantanal, Mato Grosso do Sul\"></header><main><h1>Evolução de idade das fêmeas</h1><p class=\"sub\">Escolha o período e o setor para consultar a quantidade de fêmeas por idade.</p><div class=\"filters\"><label class=\"field\">Ano inicial<input id=\"start\" type=\"number\" min=\"2026\" max=\"9999\" step=\"1\" value=\"2027\" aria-label=\"Ano inicial\"></label><label class=\"field\">Ano final<input id=\"end\" type=\"number\" min=\"2026\" max=\"9999\" step=\"1\" value=\"2035\" aria-label=\"Ano final\"></label><label class=\"field wide\">Setor<select id=\"sector\" aria-label=\"Setor\"><option value=\"\">Todos os setores</option></select></label><label class=\"field\">Ano do gráfico<select id=\"focus\" aria-label=\"Ano do gráfico\"></select></label><button id=\"print\" type=\"button\">Imprimir / salvar PDF</button><button id=\"reset\" type=\"button\">Limpar filtros</button></div><p id=\"error\" role=\"alert\"></p><p class=\"context\" id=\"context\"></p><div class=\"cards\"><div class=\"card\"><div class=\"label\">Fêmeas da base selecionada</div><div class=\"value\" id=\"total\"></div><div class=\"small\">Ativas no mapa final</div></div><div class=\"card\"><div class=\"label\" id=\"meanLabel\"></div><div class=\"value\" id=\"mean\"></div><div class=\"small\">Idade em anos completos</div></div><div class=\"card\"><div class=\"label\" id=\"groupLabel\"></div><div class=\"value\" id=\"group\"></div><div class=\"small\" id=\"groupAge\"></div></div></div><section class=\"block\"><h2 id=\"chartTitle\"></h2><div class=\"chart-wrap\"><svg id=\"chart\" viewBox=\"0 0 1080 260\" role=\"img\"></svg></div></section><section class=\"block\"><h2>Idade × ano da projeção</h2><div class=\"table-wrap\"><table id=\"matrix\"><thead></thead><tbody></tbody><tfoot></tfoot></table></div><div class=\"legend\"><span><i class=\"dot\" style=\"background:#d5e8cd\"></i>Menor quantidade</span><span><i class=\"dot\" style=\"background:#f9e5a1\"></i>Intermediária</span><span><i class=\"dot\" style=\"background:#ebab9a\"></i>Maior quantidade</span></div></section><p class=\"note\">Referência: __REFERENCE__ de cada ano. Recorte de idade: __AGES__ anos completos. Projeção das mesmas fêmeas da base atual, sem considerar novos nascimentos, compras, mortes, vendas ou descartes futuros. O setor é o registrado na base atual.</p><p class=\"note\">Fonte: mapa final de rebanho · Base salva em __UPDATED__ · Consulta em __BASEDAY__. Este arquivo contém uma cópia da base nessa data.</p></main><footer class=\"landscape\"><img src=\"data:image/jpeg;base64,\" alt=\"Paisagem da Fazenda Bodoquena — Produzir, conservar, transformar\"></footer></article><script>\nconst DATA=__DATA__, INITIAL=__INITIAL__, $=id=>document.getElementById(id), fmt=n=>n.toLocaleString('pt-BR'), decimal=n=>n.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});\n\n$('start').min=$('end').min=Number(INITIAL.baseDate.slice(0,4));$('start').value=INITIAL.start;$('end').value=INITIAL.end;for(const s of Object.keys(DATA).sort((a,b)=>a.localeCompare(b,'pt-BR')))$('sector').add(new Option(s,s));\n$('sector').value=INITIAL.section||'';function heat(n,max){if(!n)return '#f1f5ee';const t=n/max;const a=t<=.5?[213,232,205]:[249,229,161],b=t<=.5?[249,229,161]:[235,171,154],v=t<=.5?t*2:(t-.5)*2;return '#'+a.map((x,i)=>Math.round(x+(b[i]-x)*v).toString(16).padStart(2,'0')).join('')}\nfunction update(changed){for(const id of ['start','end']){const n=Number($(id).value);if(!Number.isInteger(n)||n<Number(INITIAL.baseDate.slice(0,4))||n>9999){$('error').textContent='Informe um ano inteiro a partir de 2026.';return}}$('error').textContent='';let start=+$('start').value,end=+$('end').value;if(start>end){if(changed==='start')$('end').value=start;else $('start').value=end;start=+$('start').value;end=+$('end').value}\nconst ys=Array.from({length:end-start+1},(_,i)=>start+i),old=+$('focus').value||INITIAL.focus;$('focus').replaceChildren(...ys.map(y=>new Option(y,y)));$('focus').value=String(ys.includes(old)?old:start);const focus=+$('focus').value,sector=$('sector').value,births={};for(const [s,counts] of Object.entries(DATA)){if(sector&&s!==sector)continue;for(const [birth,n]of Object.entries(counts))births[birth]=(births[birth]||0)+n}\nconst total=Object.values(births).reduce((a,b)=>a+b,0),matrix={},ages=new Set();for(const y of ys){matrix[y]={};for(const [birth,n]of Object.entries(births)){const date=String(y)+'-'+(INITIAL.monthDay||'12-31'),b=birth.split('-').map(Number),r=date.split('-').map(Number);const age=r[0]-b[0]-(r[1]<b[1]||(r[1]===b[1]&&r[2]<b[2])?1:0);if(age<(INITIAL.minAge??0)||age>(INITIAL.maxAge??9999)||date<birth)continue;matrix[y][age]=(matrix[y][age]||0)+n;ages.add(age)}}\nconst aa=[...ages].sort((a,b)=>a-b),min=aa.length?Math.min(...aa):0,maxAge=aa.length?Math.max(...aa):-1;const rows=Array.from({length:maxAge-min+1},(_,i)=>min+i);const mean=y=>Object.entries(matrix[y]).reduce((sum,[age,n])=>sum+(+age)*n,0)/(Object.values(matrix[y]).reduce((a,b)=>a+b,0)||1),counts=Object.entries(matrix[focus]).map(([a,n])=>[+a,n]).sort((a,b)=>a[0]-b[0]),largest=counts.reduce((a,b)=>b[1]>a[1]?b:a,[0,0]),maximum=Math.max(...Object.values(matrix).flatMap(c=>Object.values(c)));\n$('context').textContent=(start===end?start:start+' a '+end)+' · '+(sector||'Todos os setores')+' · Somente fêmeas';$('total').textContent=fmt(total);$('meanLabel').textContent='Idade média em '+focus;$('mean').textContent=decimal(mean(focus))+' anos';$('groupLabel').textContent='Maior grupo em '+focus;$('group').textContent=fmt(largest[1])+' fêmeas';$('groupAge').textContent=largest[0]+' anos em 31/12/'+focus;$('chartTitle').textContent='Quantidade de fêmeas por idade em '+focus;\n$('matrix').querySelector('thead').innerHTML='<tr><th scope=\"col\">Idade completa</th>'+ys.map(y=>'<th scope=\"col\">'+y+'</th>').join('')+'</tr>';$('matrix').querySelector('tbody').innerHTML=rows.map(age=>'<tr><td>'+age+(age===1?' ano':' anos')+'</td>'+ys.map(y=>{const n=matrix[y][age]||0;return '<td style=\"background:'+heat(n,maximum)+'\">'+fmt(n)+'</td>'}).join('')+'</tr>').join('');$('matrix').querySelector('tfoot').innerHTML='<tr><td>Total de fêmeas no recorte</td>'+ys.map(y=>'<td style=\"background:#ebab9a\">'+fmt(Object.values(matrix[y]).reduce((a,b)=>a+b,0))+'</td>').join('')+'</tr><tr><td>Idade média (anos)</td>'+ys.map(y=>'<td>'+decimal(mean(y))+'</td>').join('')+'</tr>';\nconst ceiling=Math.max(5,Math.ceil(largest[1]/5)*5),pitch=990/counts.length,baseline=205,height=160;let svg='';for(let i=0;i<=4;i++){const n=ceiling*i/4,y=baseline-height*i/4;svg+='<line x1=\"65\" x2=\"1060\" y1=\"'+y+'\" y2=\"'+y+'\" stroke=\"#dbe3d7\"/><text x=\"55\" y=\"'+(y+4)+'\" text-anchor=\"end\" font-size=\"11\" fill=\"#617065\">'+fmt(Math.round(n))+'</text>'}for(let i=0;i<counts.length;i++){const [age,n]=counts[i],x=65+i*pitch,h=n/ceiling*height;svg+='<rect x=\"'+(x+pitch*.2)+'\" y=\"'+(baseline-h)+'\" width=\"'+(pitch*.6)+'\" height=\"'+h+'\" fill=\"#193e32\"/><text x=\"'+(x+pitch/2)+'\" y=\"'+(baseline-h-6)+'\" text-anchor=\"middle\" font-size=\"11\" fill=\"#193e32\">'+fmt(n)+'</text><text x=\"'+(x+pitch/2)+'\" y=\"225\" text-anchor=\"middle\" font-size=\"11\" fill=\"#617065\">'+age+'</text>'}svg+='<text x=\"65\" y=\"250\" font-size=\"11\" fill=\"#617065\">Idade completa (anos)</text>';$('chart').innerHTML=svg;$('chart').setAttribute('aria-label',$('chartTitle').textContent);}\nfor(const id of ['start','end','sector','focus'])$(id).addEventListener('change',()=>update(id));$('print').addEventListener('click',()=>window.print());$('reset').addEventListener('click',()=>{$('start').value=INITIAL.start;$('end').value=INITIAL.end;$('sector').value='';$('focus').value='2027';update()});update();\n</script></body></html>";root.BodoquenaAgeReportHTML=function(data,initial){const safe=x=>JSON.stringify(x).replace(/</g,'\\u003c');const date=initial.monthDay||'12-31';return TEMPLATE.replace('__DATA__',safe(data)).replace('__INITIAL__',safe(initial)).replace('__REFERENCE__',date.slice(3)+'/'+date.slice(0,2)).replace('__AGES__',(initial.minAge??0)+' a '+(initial.maxAge??9999)).replace('__UPDATED__',initial.updatedAt?new Date(initial.updatedAt).toLocaleString('pt-BR'):'não informada').replace('__BASEDAY__',initial.baseDate.split('-').reverse().join('/'));};})(typeof window!=='undefined'?window:globalThis);